// ELParserInit initializes any static state used to implement ELParser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewELParser(). You can call this function if you wish to initialize the static state ahead
// of time.
func ELParserInit() {
	staticData := &ELParserStaticData
	staticData.once.Do(elParserInit)
}

// NewELParser produces a new parser instance for the optional input antlr.TokenStream.
func NewELParser(input antlr.TokenStream) *ELParser {
	ELParserInit()
	this := new(ELParser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &ELParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "EL.g4"

	return this
}

